using namespace std;

bool letter(char c){return ('a'<=c&&c<='z')||('A'<=c&&c<='Z');}

bool digit(char c){return '0'<=c&&c<='9';}

int main(){
string s;getline(cin,s);bool start=true,ok=!s.empty();for(unsigned char c:s){

 if(isspace(c)){start=true;continue;}

 if(letter(c)){if(start){if(!('A'<=c&&c<='Z'))ok=false;}else if(!('a'<=c&&c<='z'))ok=false;}

 start=false;}cout<<(ok?"Yes":"No")<<'\n';
